
from app.infrastructure.aws.clients.s3 import s3_client
from app.core.config import settings
from app.modules.files.constants import get_file_category


class S3Service:

    def __init__(self):
        self.s3_client = s3_client
        self.bucket_name = settings.s3_bucket_name

    def generate_upload_url(
        self,
        user_id: str,
        file_id: str,
        content_type: str,
        expires_in: int = 300,
    ) -> dict:

        category = get_file_category(content_type)

        # Same file_id generated by FileService
        object_key = (
            f"users/{user_id}/{category}/{file_id}"
        )

        presigned_url = self.s3_client.generate_presigned_url(
            ClientMethod="put_object",
            Params={
                "Bucket": self.bucket_name,
                "Key": object_key,
                "ContentType": content_type,
            },
            ExpiresIn=expires_in,
        )

        return {
            "upload_url": presigned_url,
            "object_key": object_key,
            "bucket_name": self.bucket_name,
            "category": category,
            "expires_in": expires_in,
        }
